                cols[i].append(j)

    # row types
    typ = ['B' if len(c) > 1 else 'S' for c in cols]

    # list of rows that are S and their column
    s_rows = [(i, cols[i][0]) for i in range(h) if typ[i] == 'S']
    # find minimal period p that fits types and the shift consistency
    p = 1
    while True:
        ok = True
        # types must repeat
        for i in range(h):
            if typ[i] != typ[i % p]:
                ok = False
                break
        if not ok:
            p += 1
            continue
        # check shift consistency from S rows
        shift = [None] * p
        for k in range(len(s_rows) - 1):
            i0, col0 = s_rows[k]
            i1, col1 = s_rows[k + 1]
            diff = col1 - col0
            prev_idx = (i1 - 1) % p
            if shift[prev_idx] is None:
                shift[prev_idx] = diff
            elif shift[prev_idx] != diff:
                ok = False
                break
        if not ok:
            p += 1
            continue
        # fill missing shifts with 0
        for i in range(p):
            if shift[i] is None:
                shift[i] = 0
        break

    pattern_type = typ[:p]
    pattern_shift = shift

    # previous S column for each row (needed for D)
    prev_s_col = [None] * h
    last = None
    for i in range(h):
        if typ[i] == 'S':
            last = cols[i][0]
        prev_s_col[i] = last

