    D = {}
    for i in range(h):
        if typ[i] == 'B':
            idx = i % p
            if idx not in D:
                pre = prev_s_col[i]
                if pre is not None:
                    D[idx] = {c - pre for c in cols[i]}

    # initialise result with input rows and pad to 10 rows
    result = [row[:] for row in grid]
    if len(result) < 10:
        result += [[0] * w for _ in range(10 - len(result))]

    # find the column of the last S row and the current cursor
    last_s_idx = max(i for i, t in enumerate(typ) if t == 'S')
    last_s_col = cols[last_s_idx][0]
    cur = last_s_col + pattern_shift[last_s_idx % p]

    # generate the remaining rows
    for i in range(h, 10):
        idx = i % p
        t = pattern_type[idx]
        if t == 'S':
            col = cur
            if 0 <= col < w:
                result[i][col] = val
        else:  # B
            offsets = D.get(idx, set())
            for d in offsets:
                col = cur + d
                if 0 <= col < w:
                    result[i][col] = val
        cur += pattern_shift[idx]

    return result

